contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount, address account) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        uint256 balBefore = c.balances(account); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 balAfter = c.balances(account); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        assert(balAfter >= balBefore && cBalAfter >= cBalBefore + amount);
    }
}

