// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, address account) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        uint256 balBefore;
        try c.balances(account) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 cBalBefore = address(c).balance;
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 balAfter;
        try c.balances(account) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 cBalAfter = address(c).balance;
        assertTrue(balAfter >= balBefore && cBalAfter >= cBalBefore + amount);
    }

    function testFuzz_run(uint256 amount, address account) public {
        vm.assume(account.code.length == 0 && uint160(account) > 0xffff && account != address(this) && account != address(c) && account != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && account != 0x000000000000000000636F6e736F6c652e6c6f67 && account != 0x4e59b44847b379578588920cA78FbF26c0B4956C && account != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, account);
    }

    receive() external payable {}
}
